#include "sensor_protocol.h"
static void w16(uint8_t *p,uint16_t v){p[0]=(uint8_t)(v>>8);p[1]=(uint8_t)v;}
static void w32(uint8_t *p,uint32_t v){p[0]=(uint8_t)(v>>24);p[1]=(uint8_t)(v>>16);p[2]=(uint8_t)(v>>8);p[3]=(uint8_t)v;}
static uint16_t r16(const uint8_t *p){return (uint16_t)(((uint16_t)p[0]<<8)|p[1]);}
static uint32_t r32(const uint8_t *p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
static void header(uint8_t *p,uint8_t type){w16(p,SENSOR_PROTOCOL_MAGIC);p[2]=SENSOR_PROTOCOL_VERSION;p[3]=type;}
size_t sensor_protocol_encode_registration_request(const uint8_t mac[6],uint32_t seq,uint8_t p[SENSOR_PROTOCOL_REGISTRATION_REQUEST_SIZE]){if(!mac||!p)return 0;header(p,SENSOR_PROTOCOL_TYPE_REGISTRATION_REQUEST);for(size_t i=0;i<6;i++)p[4+i]=mac[i];w32(p+10,seq);return SENSOR_PROTOCOL_REGISTRATION_REQUEST_SIZE;}
int sensor_protocol_decode_registration_response(const uint8_t *p,size_t n,sensor_registration_response_t *r){if(!p||!r||n!=SENSOR_PROTOCOL_REGISTRATION_RESPONSE_SIZE||r16(p)!=SENSOR_PROTOCOL_MAGIC||p[2]!=SENSOR_PROTOCOL_VERSION||p[3]!=SENSOR_PROTOCOL_TYPE_REGISTRATION_RESPONSE)return 0;for(size_t i=0;i<6;i++)r->mac[i]=p[4+i];r->sequence=r32(p+10);r->device_id=r16(p+14);return r->device_id<=0xff;}
size_t sensor_protocol_encode_sample(const sensor_sample_t *s,uint8_t p[SENSOR_PROTOCOL_PACKET_SIZE]){if(!s||!p||s->device_id>0xff)return 0;header(p,SENSOR_PROTOCOL_TYPE_SAMPLE);w16(p+4,s->device_id);w32(p+6,s->sequence);w32(p+10,s->timestamp_us);w16(p+14,s->status==SENSOR_STATUS_I2C_ERROR?0x4000U:(uint16_t)(s->raw_angle&0x3fffU));w32(p+16,s->sync_token);return SENSOR_PROTOCOL_PACKET_SIZE;}
size_t sensor_protocol_encode_time_sync_request(uint16_t id,uint32_t seq,uint32_t t1,uint8_t p[SENSOR_PROTOCOL_SYNC_REQUEST_SIZE]){if(!p||id>0xff)return 0;header(p,SENSOR_PROTOCOL_TYPE_TIME_SYNC_REQUEST);w16(p+4,id);w32(p+6,seq);w32(p+10,t1);return SENSOR_PROTOCOL_SYNC_REQUEST_SIZE;}
int sensor_protocol_decode_time_sync_response(const uint8_t *p,size_t n,sensor_time_sync_response_t *r){if(!p||!r||n!=SENSOR_PROTOCOL_SYNC_RESPONSE_SIZE||r16(p)!=SENSOR_PROTOCOL_MAGIC||p[2]!=SENSOR_PROTOCOL_VERSION||p[3]!=SENSOR_PROTOCOL_TYPE_TIME_SYNC_RESPONSE)return 0;r->device_id=r16(p+4);if(r->device_id>0xff)return 0;r->sequence=r32(p+6);r->device_t1_us=r32(p+10);r->server_t2_us=r32(p+14);r->server_t3_us=r32(p+18);r->sync_token=r32(p+22);return 1;}
size_t sensor_protocol_encode_time_sync_report(uint16_t id,uint32_t seq,uint32_t t1,uint32_t t4,uint32_t token,uint8_t p[SENSOR_PROTOCOL_SYNC_REPORT_SIZE]){if(!p||id>0xff||!token)return 0;header(p,SENSOR_PROTOCOL_TYPE_TIME_SYNC_REPORT);w16(p+4,id);w32(p+6,seq);w32(p+10,t1);w32(p+14,t4);w32(p+18,token);return SENSOR_PROTOCOL_SYNC_REPORT_SIZE;}
